dest = r"c:\Automtion Tools\cookies.txt"

lines = ["# Netscape HTTP Cookie File\n", "# https://curl.haxx.se/rfc/cookie_spec.html\n", "# This is a generated file!  Do not edit.\n", "\n"]

for c in cookies:
    domain = c["domain"]
    include_subdomains = "TRUE" if domain.startswith(".") else "FALSE"
    path = c.get("path", "/")
    secure = "TRUE" if c.get("secure", False) else "FALSE"
    # session cookies get far-future expiry
    exp = c.get("expirationDate", 0)
    if c.get("session", False) or not exp:
        exp = 1893456000  # 2030
    expiry = str(int(exp))
    name = c["name"]
    value = c["value"]
    lines.append(f"{domain}\t{include_subdomains}\t{path}\t{secure}\t{expiry}\t{name}\t{value}\n")

with open(dest, "w", encoding="utf-8", newline="\n") as f:
    f.writelines(lines)

print(f"OK - cookies.txt updated with {len(cookies)} cookies (LF line endings)")
with open(dest, "rb") as f:
    raw = f.read(200)
print("First 100 bytes check:", raw[:100])
